// Latest power lives only in the telemetryRuntime memory store, outside MySQL.
var packet;
try{var raw=Buffer.isBuffer(msg.payload)?msg.payload.toString():String(msg.payload);if(raw.length>32768)return null;packet=JSON.parse(raw);}catch(e){return null;}
if(!packet||packet.type!=='office_power'||packet.version!==1||packet.source_id!=='ug65-ussc'||packet.interval_minutes!==1||!Array.isArray(packet.records)||packet.records.length>8)return null;
var now=Date.now(),sampled=Date.parse(packet.sampled_at_utc);
if(!Number.isFinite(sampled)||sampled>now+5000)return null;
var previous=flow.get('office_power_latest_v1','telemetryRuntime');
if(previous&&previous.sampled<=now&&sampled<previous.sampled)return null;
var allowed=["24E124148060C6A0","24E12414806031FC","24E124148060D73E","24E1241480609886","24E1247710630110","24E124771063F466","24E1247710633F88","24E1247710638799"],seen={};
var records=packet.records.filter(function(r){return r&&typeof r.device_eui==='string'&&allowed.indexOf(r.device_eui)!==-1;});
if(records.some(function(r){if(seen[r.device_eui])return true;seen[r.device_eui]=true;return false;}))return null;
records=records.map(function(r){
    var value=typeof r.power_w==='number'&&Number.isFinite(r.power_w)&&r.power_w>=0&&r.power_w<=4294967295?r.power_w:null;
    var observed=Date.parse(r.power_w_at);
    return {device_eui:r.device_eui,power_w:value,power_w_at:Number.isFinite(observed)?new Date(observed).toISOString():null};
});
flow.set('office_power_latest_v1',{sampled:sampled,data:{type:'office_power',version:1,source_id:packet.source_id,sampled_at_utc:new Date(sampled).toISOString(),interval_minutes:1,records:records}},'telemetryRuntime');
node.status({fill:'green',shape:'dot',text:'daya diterima '+new Date(now).toLocaleTimeString()});
return null;

// Read-only HTTP endpoint; uses the existing control key and source-IP policy.
if(!msg.req||!msg.res)return null;
msg.headers={'Content-Type':'application/json','Cache-Control':'no-store'};
function reply(code,body){msg.statusCode=code;msg.payload=body;return msg;}
var address=String(msg.req.socket&&msg.req.socket.remoteAddress||'').replace(/^::ffff:/,'');
if(['100.86.6.76','127.0.0.1','::1'].indexOf(address)===-1)return reply(403,{status:'error',message:'Sumber permintaan tidak diizinkan'});
var key=String(env.get('OFFICE_CONTROL_KEY')||'');
if(key.length<32)return reply(503,{status:'error',message:'OFFICE_CONTROL_KEY belum diatur'});
if(String(msg.req.headers.authorization||'')!=='Bearer '+key)return reply(401,{status:'error',message:'Token tidak valid'});
var cached=flow.get('office_power_latest_v1','telemetryRuntime');
if(!cached)return reply(503,{status:'error',message:'Menunggu data daya dari UG65'});
return reply(200,{status:'success',data:cached.data});
